import ast

with open('/repo/benchmarks/calculate_laplacian_error.py', 'r') as f:
    source = f.read()

tree = ast.parse(source)

found_try = False
found_except_value_error = False
found_jacobi_fallback = False

for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef) and node.name == 'compute_alpha':
        for child in ast.walk(node):
            if isinstance(child, ast.Try):
                found_try = True
                for handler in child.handlers:
                    if handler.type is not None:
                        if isinstance(handler.type, ast.Name) and handler.type.id == 'ValueError':
                            found_except_value_error = True
                        elif isinstance(handler.type, ast.Attribute) and handler.type.attr == 'ValueError':
                            found_except_value_error = True
                    for stmt in ast.walk(handler):
                        if isinstance(stmt, ast.Call):
                            func = stmt.func
                            if isinstance(func, ast.Name) and func.id == 'jacobi':
                                found_jacobi_fallback = True

if found_try and found_except_value_error and found_jacobi_fallback:
    print('PASS')
    sys.exit(0)
else:
    print(f'FAIL: try={found_try}, except_ValueError={found_except_value_error}, jacobi_fallback={found_jacobi_fallback}')
    sys.exit(1)

