found_shape_check = False
found_value_error_raise = False

for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef) and node.name == 'compute_alpha':
        for child in ast.walk(node):
            if isinstance(child, ast.Raise):
                if child.exc is not None:
                    exc = child.exc
                    if isinstance(exc, ast.Call):
                        func = exc.func
                        name = ''
                        if isinstance(func, ast.Name):
                            name = func.id
                        elif isinstance(func, ast.Attribute):
                            name = func.attr
                        if name == 'ValueError':
                            found_value_error_raise = True
            src_chunk = ast.get_source_segment(source, child) or ''
            if 'ndim' in src_chunk:
                found_ndim_check = True
            if 'shape' in src_chunk:
                found_shape_check = True

if found_ndim_check and found_shape_check and found_value_error_raise:
    print('PASS')
    sys.exit(0)
else:
    print(f'FAIL: ndim_check={found_ndim_check}, shape_check={found_shape_check}, value_error={found_value_error_raise}')
    sys.exit(1)

